  if(btn){ btn._h=btn.innerHTML; btn.innerHTML='Applying…'; btn.style.pointerEvents='none'; btn.style.opacity='.7'; } if(st){ st.textContent='Working on it…'; st.style.color='var(--muted)'; }
  const tmp=document.createElement('div'); tmp.innerHTML=ed.innerHTML; const curText=(tmp.innerText||'').replace(/\n{3,}/g,'\n\n').trim();
